import {
  access,
  mkdir,
  readdir,
  readFile,
  rm,
  writeFile,
} from 'node:fs/promises';
import { basename, join, resolve } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

import StyleDictionary from 'style-dictionary';

import { COLOR_FILE, DEFAULT_THEME, HIDDEN_FILE } from './config.js';
import { transforms } from './transforms.js';
import {
  findContrastFailures,
  findHiddenTokens,
  findUnresolvedReferences,
} from './verify.js';

const HEADER =
  '/* Generated by @dy/tokens from Figma variables. Do not edit. */';

/**
 * @typedef {{ name: string, $type?: string, $value: unknown, filePath: string }} BuiltToken
 * @typedef {import('./verify.js').ContrastPair} ContrastPair
 */

/**
 * Resolves and transforms one theme × mode combination with Style Dictionary.
 *
 * @param {{ sources: string[] }} options
 * @returns {Promise<BuiltToken[]>}
 */
async function resolveTokens({ sources }) {
  const dictionary = new StyleDictionary(
    {
      source: sources,
      hooks: { transforms },
      platforms: { css: { transforms: Object.keys(transforms) } },
      log: { verbosity: 'silent', warnings: 'error' },
    },
    // Initialize explicitly: errors thrown during the constructor's own
    // initialization are swallowed and leave getPlatformTokens waiting forever
    { init: false },
  );
  await dictionary.init();
  const { allTokens } = await dictionary.getPlatformTokens('css');
  return /** @type {BuiltToken[]} */ (allTokens);
}

/**
 * @param {{ layer: string, selector: string, tokens: BuiltToken[] }} options
 * @returns {string} One cascade layer block of custom properties
 */
export function formatLayer({ layer, selector, tokens }) {
  const declarations = [...tokens]
    .sort((first, second) => first.name.localeCompare(second.name))
    .map((token) => `    --${token.name}: ${String(token.$value)};`);

  return `@layer ${layer} {\n  ${selector} {\n${declarations.join('\n')}\n  }\n}\n`;
}

/**
 * Builds CSS and a manifest from the DTCG files in `srcDir`.
 *
 * @param {{ srcDir: string, distDir: string, pairs: ContrastPair[] }} options
 * @returns {Promise<{ files: string[], tokenCount: number } | null>} null when there are no tokens yet
 */
export async function buildTokens({ srcDir, distDir, pairs }) {
  try {
    await access(srcDir);
  } catch {
    return null;
  }

  const fileNames = (await readdir(srcDir)).filter((fileName) =>
    fileName.endsWith('.json'),
  );
  const themes = fileNames.flatMap(
    (fileName) => /^theme\.([^.]+)\.json$/.exec(fileName)?.[1] ?? [],
  );
  const modes = fileNames.flatMap(
    (fileName) => /^color\.([^.]+)\.json$/.exec(fileName)?.[1] ?? [],
  );

  if (themes.length === 0 || modes.length === 0) {
    throw new Error(
      `${srcDir} needs at least one theme.*.json and one color.*.json file.`,
    );
  }
  if (modes.length > 1) {
    // Dark mode will combine modes with light-dark(); not built until it exists in Figma
    throw new Error(
      `Multiple color modes (${modes.join(', ')}) aren't supported by the build yet.`,
    );
  }
  if (!themes.includes(DEFAULT_THEME)) {
    throw new Error(
      `The default theme "${DEFAULT_THEME}" has no theme.${DEFAULT_THEME}.json.`,
    );
  }

  const sharedFiles = fileNames.filter(
    (fileName) => !/^(theme|color)\./.test(fileName),
  );
  const [mode] = modes;

  /** @type {BuiltToken[]} */
  let neutralTokens = [];
  /** @type {Set<string>} */
  const hiddenNames = new Set();
  /** @type {Map<string, BuiltToken[]>} */
  const colorTokensByTheme = new Map();

  for (const theme of themes) {
    const tokens = await resolveTokens({
      sources: [
        ...sharedFiles,
        `theme.${theme}.json`,
        `color.${String(mode)}.json`,
      ].map((fileName) => join(srcDir, fileName)),
    });
    for (const token of tokens) {
      if (HIDDEN_FILE.test(basename(token.filePath))) {
        hiddenNames.add(token.name);
      }
    }
    const shipped = tokens.filter(
      (token) => !HIDDEN_FILE.test(basename(token.filePath)),
    );
    colorTokensByTheme.set(
      theme,
      shipped.filter((token) => COLOR_FILE.test(basename(token.filePath))),
    );
    if (theme === DEFAULT_THEME) {
      neutralTokens = shipped.filter(
        (token) => !COLOR_FILE.test(basename(token.filePath)),
      );
    }
  }

  const tokensCss = formatLayer({
    layer: 'dy.tokens',
    selector: ':root',
    tokens: neutralTokens,
  });
  const themeCss = new Map(
    [...colorTokensByTheme].map(([theme, tokens]) => [
      theme,
      formatLayer({
        layer: 'dy.themes',
        selector:
          theme === DEFAULT_THEME
            ? `:root,\n  [data-theme='${theme}']`
            : `[data-theme='${theme}']`,
        tokens,
      }),
    ]),
  );
  // The layer order belongs to @dy/css, whose reset declares it, so the
  // bundle only fills the dy.tokens and dy.themes layers.
  const bundle = [HEADER, tokensCss, ...themeCss.values()].join('\n\n');

  // Verify before writing, so a failing build never leaves partial output
  const defaultColors = colorTokensByTheme.get(DEFAULT_THEME) ?? [];
  const problems = [
    ...findHiddenTokens({ css: bundle, hiddenNames: [...hiddenNames] }).map(
      (name) => `Hidden token shipped: --${name}`,
    ),
    ...findUnresolvedReferences({ css: bundle }).map(
      (line) => `Unresolved reference: ${line}`,
    ),
    ...[...colorTokensByTheme].flatMap(([theme, tokens]) =>
      findContrastFailures({
        colors: new Map(
          tokens.map((token) => [token.name, String(token.$value)]),
        ),
        pairs,
      }).map((failure) => `Contrast (${theme}): ${failure}`),
    ),
  ];
  if (problems.length > 0) {
    throw new Error(
      `Token build failed verification:\n- ${problems.join('\n- ')}`,
    );
  }

  await rm(distDir, { recursive: true, force: true });
  await mkdir(join(distDir, 'css', 'themes'), { recursive: true });

  /** @type {[string, string][]} */
  const outputs = [
    ['css/tokens.css', `${HEADER}\n\n${tokensCss}`],
    ...[...themeCss].map(
      ([theme, css]) =>
        /** @type {[string, string]} */ ([
          `css/themes/${theme}.css`,
          `${HEADER}\n\n${css}`,
        ]),
    ),
    ['css/dy.css', bundle],
    [
      'manifest.json',
      `${JSON.stringify(
        {
          defaultTheme: DEFAULT_THEME,
          themes,
          modes,
          tokens: Object.fromEntries(
            [...neutralTokens, ...defaultColors]
              .sort((first, second) => first.name.localeCompare(second.name))
              .map((token) => [
                token.name,
                { type: token.$type, value: token.$value },
              ]),
          ),
        },
        null,
        2,
      )}\n`,
    ],
  ];
  for (const [path, content] of outputs) {
    await writeFile(join(distDir, path), content);
  }

  return {
    files: outputs.map(([path]) => path),
    tokenCount: neutralTokens.length + defaultColors.length,
  };
}

async function main() {
  const packageDir = resolve(fileURLToPath(import.meta.url), '../..');
  const { pairs } = JSON.parse(
    await readFile(join(packageDir, 'contrast-pairs.json'), 'utf8'),
  );
  const result = await buildTokens({
    srcDir: join(packageDir, 'src'),
    distDir: join(packageDir, 'dist'),
    pairs,
  });

  if (!result) {
    process.stdout.write(
      'No tokens in src/ yet. Run /sync-tokens to sync them from Figma.\n',
    );
    return;
  }
  process.stdout.write(
    `Built ${String(result.tokenCount)} tokens:\n${result.files.map((path) => `- dist/${path}`).join('\n')}\n`,
  );
}

if (import.meta.url === pathToFileURL(process.argv[1] ?? '').href) {
  await main();
}
